		})
		if err != nil {
			return err
		}
		_, err = ec2.NewVpcPeeringConnectionAccepter(ctx, "aws-peering-resource", &ec2.VpcPeeringConnectionAccepterArgs{
			VpcPeeringConnectionId: peering_resource.AwsPeeringId,
			AutoAccept:             pulumi.Bool(true),
