package main

import (
	"fmt"

	"github.com/RedisLabs/pulumi-rediscloud/sdk/go/rediscloud"
	"github.com/pulumi/pulumi-gcp/sdk/v10/go/gcp/compute"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		subscription_resource, err := rediscloud.NewActiveActiveSubscription(ctx, "subscription-resource", nil)
		if err != nil {
			return err
		}
		network, err := compute.LookupNetwork(ctx, &compute.LookupNetworkArgs{
			Project: pulumi.StringRef("my-gcp-project"),
			Name:    pulumi.StringRef("my-gcp-vpc"),
		}, nil)
		if err != nil {
			return err
		}
		peering_resource, err := rediscloud.NewActiveActiveSubscriptionPeering(ctx, "peering-resource", &rediscloud.ActiveActiveSubscriptionPeeringArgs{
			SubscriptionId: subscription_resource.ID(),
			SourceRegion:   pulumi.String("us-central1"),
			ProviderName:   pulumi.String("GCP"),
			GcpProjectId:   pulumi.String(network.Project),
			GcpNetworkName: pulumi.String(network.Name),
		})
		if err != nil {
			return err
		}
		_, err = compute.NewNetworkPeering(ctx, "gcp-peering-resource", &compute.NetworkPeeringArgs{
			Name:    pulumi.String("peering-gcp-example"),
			Network: pulumi.String(network.SelfLink),
			PeerNetwork: peering_resource.GcpRedisProjectId.ApplyT(func(gcpRedisProjectId string) (string, error) {
				return fmt.Sprintf("https://www.googleapis.com/compute/v1/projects/%v/global/networks/%v", gcpRedisProjectId, example.GcpRedisNetworkName), nil
			}).(pulumi.StringOutput),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
