public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        // Accept the TGW invitation (Redis Cloud side)
        var example = new ActiveActiveTransitGatewayInvitationAcceptor("example", ActiveActiveTransitGatewayInvitationAcceptorArgs.builder()
            .subscriptionId(exampleRediscloudActiveActiveSubscription.get("id"))
            .regionId(1)
            .tgwInvitationId(exampleRediscloudActiveActiveTransitGatewayInvitations.get("invitations")[0].get("id"))
            .action("accept")
            .build());

        // Create the attachment
        var exampleActiveActiveTransitGatewayAttachment = new ActiveActiveTransitGatewayAttachment("exampleActiveActiveTransitGatewayAttachment", ActiveActiveTransitGatewayAttachmentArgs.builder()
            .subscriptionId(exampleRediscloudActiveActiveSubscription.get("id"))
            .regionId("1")
            .tgwId(exampleRediscloudActiveActiveTransitGateway.get("tgwId"))
            .build());

        // Accept on AWS side
        var exampleVpcAttachmentAccepter = new VpcAttachmentAccepter("exampleVpcAttachmentAccepter", VpcAttachmentAccepterArgs.builder()
            .transitGatewayAttachmentId(exampleActiveActiveTransitGatewayAttachment.attachmentUid())
            .build());

        // Configure CIDRs (depends on AWS acceptance)
        var exampleActiveActiveTransitGatewayRoute = new ActiveActiveTransitGatewayRoute("exampleActiveActiveTransitGatewayRoute", ActiveActiveTransitGatewayRouteArgs.builder()
            .subscriptionId(exampleRediscloudActiveActiveSubscription.get("id"))
            .regionId("1")
            .tgwId(exampleRediscloudActiveActiveTransitGateway.get("tgwId"))
            .cidrs(            
                "10.10.20.0/24",
                "10.10.30.0/24")
            .build(), CustomResourceOptions.builder()
                .dependsOn(exampleVpcAttachmentAccepter)
                .build());

    }
}
