rediscloud:index/privateServiceConnectEn.description:
Manages a Private Service Connect to a Pro subscription in your Redis Enterprise Cloud Account.

## Example Usage

The example below creates a Private Service Connect Endpoint in a Pro subscription, the respective GCP resources 
and accepts the endpoint. 

Please note that an endpoint can only be accepted after, the forwarding rules in GCP are created.

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as gcp from "@pulumi/gcp";
import * as rediscloud from "@rediscloud/pulumi-rediscloud";

const card = rediscloud.getPaymentMethod({
    cardType: "Visa",
});
const subscription = new rediscloud.Subscription("subscription", {
    cloudProvider: {
        regions: [{
            region: gcpRegion,
            networkingDeploymentCidr: "10.0.1.0/24",
        }],
        provider: "GCP",
    },
    creationPlan: {
        datasetSizeInGb: 15,
        quantity: 1,
        replication: true,
        throughputMeasurementBy: "operations-per-second",
        throughputMeasurementValue: 20000,
    },
    name: "subscription-name",
    paymentMethodId: card.then(card => card.id),
});
const serviceAttachmentCount = 1;
const service = new rediscloud.PrivateServiceConnect("service", {subscriptionId: subscription.id});
const endpoint = new rediscloud.PrivateServiceConnectEndpoint("endpoint", {
    subscriptionId: subscription.id,
    privateServiceConnectServiceId: service.privateServiceConnectServiceId,
    gcpProjectId: gcpProjectId,
    gcpVpcName: gcpVpcName,
    gcpVpcSubnetName: gcpSubnetName,
    endpointConnectionName: pulumi.interpolate`redis-${subscription.id}`,
});
const network = gcp.compute.getNetwork({
    project: gcpProjectId,
    name: gcpVpcName,
});
const subnet = gcp.compute.getSubnetwork({
    project: gcpProjectId,
    name: gcpSubnetName,
    region: gcpRegion,
});
const _default: gcp.compute.Address[] = [];
for (let range = 0; range < serviceAttachmentCount; range++) {
    _default.push(new gcp.compute.Address(`default-${range}`, {
        project: gcpProjectId,
        name: endpoint.serviceAttachments.apply(serviceAttachments => serviceAttachments[range].ipAddressName),
        subnetwork: subnet.then(subnet => subnet.id),
        addressType: "INTERNAL",
        region: gcpRegion,
    }));
}
const defaultForwardingRule: gcp.compute.ForwardingRule[] = [];
for (let range = 0; range < serviceAttachmentCount; range++) {
    defaultForwardingRule.push(new gcp.compute.ForwardingRule(`default-${range}`, {
        name: endpoint.serviceAttachments.apply(serviceAttachments => serviceAttachments[range].forwardingRuleName),
        project: gcpProjectId,
        region: gcpRegion,
        ipAddress: _default[range].id,
        network: gcpVpcName,
        target: endpoint.serviceAttachments.apply(serviceAttachments => serviceAttachments[range].name),
        loadBalancingScheme: "",
    }));
}
const redisResponsePolicy = new gcp.dns.ResponsePolicy("redis_response_policy", {
    networks: [{
        networkUrl: network.then(network => network.id),
    }],
    responsePolicyName: `redis-${gcpVpcName}`,
    project: gcpProjectId,
});
const redisResponsePolicyRules: gcp.dns.ResponsePolicyRule[] = [];
for (let range = 0; range < serviceAttachmentCount; range++) {
    redisResponsePolicyRules.push(new gcp.dns.ResponsePolicyRule(`redis_response_policy_rules-${range}`, {
        localData: {
            localDatas: [{
                name: endpoint.serviceAttachments.apply(serviceAttachments => serviceAttachments[range].dnsRecord),
                type: "A",
                ttl: 300,
                rrdatas: [_default[range].address],
            }],
        },
        project: gcpProjectId,
        responsePolicy: redisResponsePolicy.responsePolicyName,
        ruleName: endpoint.serviceAttachments.apply(serviceAttachments => `${serviceAttachments[range].forwardingRuleName}-${gcpRegion}-rule`),
        dnsName: endpoint.serviceAttachments.apply(serviceAttachments => serviceAttachments[range].dnsRecord),
    }));
}
const accepter = new rediscloud.PrivateServiceConnectEndpointAccepter("accepter", {
    subscriptionId: subscription.id,
    privateServiceConnectServiceId: service.privateServiceConnectServiceId,
    privateServiceConnectEndpointId: endpoint.privateServiceConnectEndpointId,
    action: "accept",
}, {
    dependsOn: [defaultForwardingRule],
});
