terraform {
  required_providers {
    gcp = {
      source = "pulumi/gcp"
    }
    rediscloud = {
      source = "pulumi/rediscloud"
    }
  }
}

data "rediscloud_payment_method" "card" {
  card_type = "Visa"
}
data "gcp_compute_network" "network" {
  project = gcpProjectId
  name    = gcpVpcName
}
data "gcp_compute_subnetwork" "subnet" {
  project = gcpProjectId
  name    = gcpSubnetName
  region  = gcpRegion
}

resource "rediscloud_subscription" "subscription" {
  lifecycle {
    create_before_destroy = true
  }
  cloud_provider {
    region {
      region                     = gcpRegion
      networking_deployment_cidr = "10.0.1.0/24"
    }
    provider = "GCP"
  }
  creation_plan {
    dataset_size_in_gb           = 15
    quantity                     = 1
    replication                  = true
    throughput_measurement_by    = "operations-per-second"
    throughput_measurement_value = 20000
  }
  name              = "subscription-name"
  payment_method_id = data.rediscloud_payment_method.card.id
}
resource "rediscloud_private_service_connect" "service" {
  lifecycle {
    create_before_destroy = true
  }
  subscription_id = rediscloud_subscription.subscription.id
}
resource "rediscloud_private_service_connect_endpoint" "endpoint" {
  lifecycle {
    create_before_destroy = true
  }
  subscription_id                    = rediscloud_subscription.subscription.id
  private_service_connect_service_id = rediscloud_private_service_connect.service.private_service_connect_service_id
  gcp_project_id                     = gcpProjectId
  gcp_vpc_name                       = gcpVpcName
  gcp_vpc_subnet_name                = gcpSubnetName
  endpoint_connection_name           ="redis-${rediscloud_subscription.subscription.id}"
}
resource "gcp_compute_address" "default" {
  count = local.serviceAttachmentCount
  pulumi {
    name ="default-${count.index}"
  }
  lifecycle {
    create_before_destroy = true
  }
  project      = gcpProjectId
  name         = rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].ip_address_name
  subnetwork   = data.gcp_compute_subnetwork.subnet.id
  address_type = "INTERNAL"
  region       = gcpRegion
}
resource "gcp_compute_forwarding_rule" "default" {
  count = local.serviceAttachmentCount
  pulumi {
    name ="default-${count.index}"
  }
  lifecycle {
    create_before_destroy = true
  }
  name                  = rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].forwarding_rule_name
  project               = gcpProjectId
  region                = gcpRegion
  ip_address            = gcp_compute_address.default[count.index].id
  network               = gcpVpcName
  target                = rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].name
  load_balancing_scheme = ""
}
resource "gcp_dns_response_policy" "redis_response_policy" {
  lifecycle {
    create_before_destroy = true
  }
  networks {
    network_url = data.gcp_compute_network.network.id
  }
  response_policy_name ="redis-${gcpVpcName}"
  project              = gcpProjectId
}
resource "gcp_dns_response_policy_rule" "redis_response_policy_rules" {
  count = local.serviceAttachmentCount
  pulumi {
    name ="redis_response_policy_rules-${count.index}"
  }
  lifecycle {
    create_before_destroy = true
  }
  local_data = {
    local_datas = [{
      name    = rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].dns_record
      type    = "A"
      ttl     = 300
      rrdatas = [gcp_compute_address.default[count.index].address]
    }]
  }
  project         = gcpProjectId
  response_policy = gcp_dns_response_policy.redis_response_policy.response_policy_name
  rule_name       ="${rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].forwarding_rule_name}-${gcpRegion}-rule"
  dns_name        = rediscloud_private_service_connect_endpoint.endpoint.service_attachments[count.index].dns_record
}
resource "rediscloud_private_service_connect_endpoint_accepter" "accepter" {
  depends_on = [gcp_compute_forwarding_rule.default]
  lifecycle {
    create_before_destroy = true
  }
  subscription_id                     = rediscloud_subscription.subscription.id
  private_service_connect_service_id  = rediscloud_private_service_connect.service.private_service_connect_service_id
  private_service_connect_endpoint_id = rediscloud_private_service_connect_endpoint.endpoint.private_service_connect_endpoint_id
  action                              = "accept"
}
locals {
  serviceAttachmentCount = 1
}
