import com.pulumi.aws.ec2transitgateway.VpcAttachmentAccepterArgs;
import com.redislabs.rediscloud.TransitGatewayRoute;
import com.redislabs.rediscloud.TransitGatewayRouteArgs;
import com.pulumi.resources.CustomResourceOptions;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        // Accept the TGW invitation (Redis Cloud side)
        var example = new TransitGatewayInvitationAcceptor("example", TransitGatewayInvitationAcceptorArgs.builder()
            .subscriptionId(exampleRediscloudSubscription.get("id"))
            .tgwInvitationId(exampleRediscloudTransitGatewayInvitations.get("invitations")[0].get("id"))
            .action("accept")
            .build());

        // Create the attachment
        var exampleTransitGatewayAttachment = new TransitGatewayAttachment("exampleTransitGatewayAttachment", TransitGatewayAttachmentArgs.builder()
            .subscriptionId(exampleRediscloudSubscription.get("id"))
            .tgwId(exampleRediscloudTransitGateway.get("tgwId"))
            .build());

        // Accept on AWS side
        var exampleVpcAttachmentAccepter = new VpcAttachmentAccepter("exampleVpcAttachmentAccepter", VpcAttachmentAccepterArgs.builder()
            .transitGatewayAttachmentId(exampleTransitGatewayAttachment.attachmentUid())
            .build());

        // Configure CIDRs (depends on AWS acceptance)
        var exampleTransitGatewayRoute = new TransitGatewayRoute("exampleTransitGatewayRoute", TransitGatewayRouteArgs.builder()
            .subscriptionId(exampleRediscloudSubscription.get("id"))
            .tgwId(exampleRediscloudTransitGateway.get("tgwId"))
            .cidrs(            
                "10.10.20.0/24",
                "10.10.30.0/24")
            .build(), CustomResourceOptions.builder()
                .dependsOn(exampleVpcAttachmentAccepter)
                .build());

    }
}
```
